47	5. Step 1：P标签提取（QuickApp安全版）
48	function extractP(html) {
49	    const res = [];
50	    let i = 0;
51	
52	    while (true) {
53	        let s = html.indexOf("<p", i);
54	        if (s === -1) break;
55	
56	        let e = html.indexOf("</p>", s);
57	        if (e === -1) break;
58	
59	        let text = html.slice(s, e);
60	
61	        res.push({
62	            text,
63	            len: text.length,
64	            score: 0,
65	            isAd: false
66	        });
67	
68	        i = e + 4;
69	
70	        if (res.length >= 64) break;
71	    }
72	
73	    return res;
74	}
