90	7. Step 3：基础评分（整数版）
91	function baseScore(p) {
92	    let s = 0;
93	
94	    // 中文密度
95	    let han = 0;
96	    for (let i = 0; i < p.text.length; i++) {
97	        let c = p.text.charCodeAt(i);
98	        if (c >= 0x4e00 && c <= 0x9fa5) han++;
99	    }
100	
101	    let ratio = (han * 1000) / (p.len + 1);
102	    if (ratio > 700) s += 300;
103	    else s -= 100;
104	
105	    // 末尾标点
106	    let last = p.text[p.text.length - 1];
107	    if (last === "。" || last === "！" || last === "？") {
108	        s += 300;
109	    } else {
110	        s -= 50;
111	    }
112	
113	    // 副标题弱增强
114	    if (p.len < 18) {
115	        s += 80;
116	    }
117	
118	    return s;
119	}
120	8. Step 4：单向邻域增强（i-1）
121	function smooth(ps) {
122	    const out = [];
123	
124	    for (let i = 0; i < ps.length; i++) {
125	        let s = ps[i].score;
126	
127	        if (i > 0 && !ps[i-1].isAd) {
128	            s += (ps[i-1].score * 3) / 10;
129	        }
130	
131	        out[i] = s;
132	    }
133	
134	    return out;
135	}
136	9. Step 5：Kadane-lite（最终正文区间）
137	function kadane(arr) {
138	    let max = -1e9;
139	    let sum = 0;
140	
141	    let start = 0;
142	    let bestL = 0, bestR = 0;
143	
144	    for (let i = 0; i < arr.length; i++) {
145	
146	        if (sum <= 0) {
147	            sum = arr[i];
148	            start = i;
149	        } else {
150	            sum += arr[i];
151	        }
152	
153	        if (sum > max) {
154	            max = sum;
155	            bestL = start;
156	            bestR = i;
157	        }
158	    }
159	
160	    return { bestL, bestR };
161	}
162	10. 主函数（Tecko-R Final）
163	function teckoR(html) {
164	
165	    const ps = extractP(html);
166	
167	    structFilter(ps);
168	
169	    for (let i = 0; i < ps.length; i++) {
170	        ps[i].score = baseScore(ps[i]);
171	
172	        if (ps[i].isAd) {
173	            ps[i].score = Math.min(ps[i].score, 10);
174	        }
175	    }
176	
177	    const sm = smooth(ps);
178	
179	    const region = kadane(sm);
180	
181	    let out = "";
182	
183	    for (let i = region.bestL; i <= region.bestR; i++) {
184	        out += ps[i].text;
185	    }
186	
187	    return out;
188	}
