243	我们把一个“多模型系统设计问题”，压缩成了一个 QuickApp 可运行的单循环数组算法。

1	/**
2	 * Tecko-v2: 完整新闻正文提取管线
3	 * 从 URL 获取 → 重定向追踪 → SPA 检测 → 正文提取 → 后处理 → 输出纯文本
4	 *
5	 * 适配 QuickApp (JerryScript) 环境：无 DOM API，纯字符串扫描
6	 * 基于 Tecko-R 算法：单遍流式 DOM 语义过滤 + 固定窗口能量评分 + Kadane 正文区间检测
7	 */
8	
9	// ==================== 配置 ====================
10	
11	var MAX_P = 64        // 最大段落数
12	var INT_SCALE = 1000  // 整数运算缩放因子
13	var MAX_REDIRECT = 5  // 最大重定向次数
14	
15	// LQB 参数
16	var LQB_LOW_THRESHOLD = 120
17	var LQB_WINDOW_LIMIT = 3
18	
19	// adTTL 参数
20	var AD_TTL_INIT = 3
21	var AD_DECAY = 1
22	var AD_BOOST_NEAR_AD = 0.15
23	
24	// 语义容器特征词（div id/class 包含这些词时视为语义容器）
25	var SEMANTIC_WORDS = ["content", "article", "detail", "main", "body", "text"]
26	
27	// 排除标签（这些标签内的内容永远不进入正文）
28	var EXCLUDED_TAGS = ["nav", "footer", "aside", "header"]
29	
30	// ==================== Step 0: HTTP 获取 ====================
31	
32	/**
33	 * 获取原始 HTML 文本（需外部提供 fetch 实现）
34	 * @param {string} url - 请求 URL
35	 * @param {object} fetchImpl - fetch 实现，需支持 fetch({ url, method, header, success, fail })
36	 * @returns {Promise<string|{redirect: string}>}
37	 */
38	function fetchText(url, fetchImpl) {
39	  return new Promise(function (resolve, reject) {
40	    var isCompleted = false
41	    var timeoutId = setTimeout(function () {
42	      if (!isCompleted) {
43	        isCompleted = true
44	        reject(new Error("Timeout"))
45	      }
46	    }, 60000)
47	
48	    fetchImpl({
49	      url: url,
50	      method: "GET",
51	      header: {
52	        "User-Agent": "Mozilla/5.0 (Linux; Android 10; SM-G975F) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/83.0.4103.106 Mobile Safari/537.36"
53	      },
54	      success: function (res) {
55	        if (isCompleted) return
56	        isCompleted = true
57	        clearTimeout(timeoutId)
58	
59	        var code = res.code || res.statusCode
60	        var data = res.data !== undefined ? res.data : res.result
61	        var headers = res.headers || {}
62	
63	        // 处理 3xx 重定向
64	        if (code >= 300 && code < 400) {
65	          var location = headers["location"] || headers["Location"] || ""
66	          if (location) {
67	            resolve({ redirect: location })
68	            return
69	          }
70	        }
71	
72	        if (typeof data === "string") {
73	          resolve(data)
74	        } else if (typeof data === "object" && data !== null) {
75	          try { resolve(JSON.stringify(data)) } catch (e) { resolve("") }
76	        } else {
77	          resolve("")
78	        }
79	      },
80	      fail: function (data, code) {
81	        if (isCompleted) return
82	        isCompleted = true
83	        clearTimeout(timeoutId)
84	        reject(new Error("Fetch failed: " + code))
85	      }
86	    })
87	  })
88	}
