90	// ==================== Step 1: 段落提取（字符串状态机 + 有界子树传播） ====================
91	
92	function extractP(html) {
93	  var res = []
94	  var lower = html.toLowerCase()
95	  var len = html.length
96	  var pos = 0
97	  var inExcluded = 0
98	  var inSemantic = 0
99	  var inPlain = 0
100	
101	  while (pos < len) {
102	    var ltPos = lower.indexOf("<", pos)
103	    if (ltPos === -1) break
104	
105	    // 检测排除标签
106	    var skipEx = false
107	    for (var ei = 0; ei < EXCLUDED_TAGS.length; ei++) {
108	      var exTag = EXCLUDED_TAGS[ei]
109	      var exOpen = "<" + exTag
110	      if (lower.indexOf(exOpen, ltPos) === ltPos &&
111	          (ltPos + exOpen.length >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + exOpen.length)) !== -1)) {
112	        var exClose = lower.indexOf("</" + exTag + ">", ltPos + exOpen.length)
113	        if (exClose === -1) { pos = len; skipEx = true; break }
114	        pos = exClose + exTag.length + 3
115	        skipEx = true
116	        break
117	      }
118	      var exCloseTag = "</" + exTag + ">"
119	      if (lower.indexOf(exCloseTag, ltPos) === ltPos) {
120	        if (inExcluded > 0) inExcluded--
121	        pos = ltPos + exCloseTag.length
122	        skipEx = true
123	        break
124	      }
125	    }
126	    if (skipEx) continue
127	    if (pos > ltPos) continue
128	
129	    // 检测语义容器开标签
130	    if (inExcluded === 0) {
131	      var containerTags = ["article", "section"]
132	      var foundContainer = false
133	      for (var ci = 0; ci < containerTags.length; ci++) {
134	        var cTag = containerTags[ci]
135	        var cOpen = "<" + cTag
136	        if (lower.indexOf(cOpen, ltPos) === ltPos &&
137	            (ltPos + cOpen.length >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + cOpen.length)) !== -1)) {
138	          inSemantic++
139	          pos = ltPos + cOpen.length
140	          foundContainer = true
141	          break
142	        }
143	      }
144	      if (foundContainer) continue
145	
146	      // 语义 div 检测
147	      if (lower.indexOf("<div", ltPos) === ltPos &&
148	          (ltPos + 4 >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + 4)) !== -1)) {
149	        var divEnd = lower.indexOf(">", ltPos)
150	        if (divEnd === -1) break
151	        var divAttrs = lower.substring(ltPos, divEnd + 1)
152	        var isSemantic = false
153	        for (var si = 0; si < SEMANTIC_WORDS.length; si++) {
154	          if (divAttrs.indexOf(SEMANTIC_WORDS[si]) !== -1) {
155	            isSemantic = true
156	            break
157	          }
158	        }
159	        if (isSemantic) { inSemantic++ } else { inPlain++ }
160	        pos = divEnd + 1
161	        continue
162	      }
163	    }
164	
165	    // 检测容器闭标签
166	    if (lower.indexOf("</article>", ltPos) === ltPos) {
167	      if (inSemantic > 0) inSemantic--
168	      pos = ltPos + 10; continue
169	    }
170	    if (lower.indexOf("</section>", ltPos) === ltPos) {
171	      if (inSemantic > 0) inSemantic--
172	      pos = ltPos + 10; continue
173	    }
174	    if (lower.indexOf("</div>", ltPos) === ltPos) {
175	      if (inSemantic > 0) inSemantic--
176	      else if (inPlain > 0) inPlain--
177	      pos = ltPos + 6; continue
178	    }
179	
180	    // P 标签提取（仅在语义容器内）
181	    if (inExcluded === 0 && inSemantic > 0 && inPlain === 0) {
182	      if (lower.indexOf("<p", ltPos) === ltPos &&
183	          (ltPos + 2 >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + 2)) !== -1)) {
184	        var pClose = lower.indexOf("</p>", ltPos + 2)
185	        if (pClose === -1) break
186	        var text = html.substring(ltPos, pClose + 4)
187	        if (text.length > 10) {
188	          res.push({ text: text, len: text.length, score: 0, isAd: false, lowScoreStreak: 0, adTTL: 0, adFlag: 0 })
189	          if (res.length >= MAX_P) break
190	        }
191	        pos = pClose + 4
192	        continue
193	      }
194	    }
195	
196	    // 跳过 script/style 标签
197	    if (lower.indexOf("<script", ltPos) === ltPos &&
198	        (ltPos + 7 >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + 7)) !== -1)) {
199	      var sEnd = lower.indexOf("</script>", ltPos + 7)
200	      pos = sEnd === -1 ? len : sEnd + 9; continue
201	    }
202	    if (lower.indexOf("<style", ltPos) === ltPos &&
203	        (ltPos + 6 >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + 6)) !== -1)) {
204	      var stEnd = lower.indexOf("</style>", ltPos + 6)
205	      pos = stEnd === -1 ? len : stEnd + 8; continue
206	    }
207	
208	    pos = ltPos + 1
209	  }
210	
211	  // Fallback：无语义容器时，提取排除区外的 P 标签
212	  if (res.length === 0) {
213	    pos = 0
214	    while (pos < len) {
215	      var lt2 = lower.indexOf("<", pos)
216	      if (lt2 === -1) break
217	
218	      var skip = false
219	      for (var fi = 0; fi < EXCLUDED_TAGS.length; fi++) {
220	        var fTag = EXCLUDED_TAGS[fi]
221	        if (lower.indexOf("<" + fTag, lt2) === lt2 &&
222	            (lt2 + fTag.length + 1 >= len || " >/\n\r\t".indexOf(lower.charAt(lt2 + fTag.length + 1)) !== -1)) {
223	          var fClose = lower.indexOf("</" + fTag + ">", lt2 + fTag.length + 1)
224	          pos = fClose === -1 ? len : fClose + fTag.length + 3
225	          skip = true; break
226	        }
227	      }
228	      if (skip) continue
229	
230	      if (lower.indexOf("<p", lt2) === lt2 &&
231	          (lt2 + 2 >= len || " >/\n\r\t".indexOf(lower.charAt(lt2 + 2)) !== -1)) {
232	        var pEnd = lower.indexOf("</p>", lt2 + 2)
233	        if (pEnd === -1) break
234	        var t = html.substring(lt2, pEnd + 4)
235	        if (t.length > 10) {
236	          res.push({ text: t, len: t.length, score: 0, isAd: false, lowScoreStreak: 0, adTTL: 0, adFlag: 0 })
237	          if (res.length >= MAX_P) break
238	        }
239	        pos = pEnd + 4; continue
240	      }
241	
242	      if (lower.indexOf("<script", lt2) === lt2 &&
243	          (lt2 + 7 >= len || " >/\n\r\t".indexOf(lower.charAt(lt2 + 7)) !== -1)) {
244	        var scrEnd = lower.indexOf("</script>", lt2 + 7)
245	        pos = scrEnd === -1 ? len : scrEnd + 9; continue
246	      }
247	      if (lower.indexOf("<style", lt2) === lt2 &&
248	          (lt2 + 6 >= len || " >/\n\r\t".indexOf(lower.charAt(lt2 + 6)) !== -1)) {
249	        var styEnd = lower.indexOf("</style>", lt2 + 6)
250	        pos = styEnd === -1 ? len : styEnd + 8; continue
251	      }
252	
253	      pos = lt2 + 1
254	    }
255	  }
256	
257	  return res
258	}
