260	// ==================== Step 2: 结构过滤（长度桶 + 区间相似性） ====================
261	
262	function getBucket(len) {
263	  if (len < 20) return 0
264	  if (len < 50) return 1
265	  if (len < 100) return 2
266	  if (len < 200) return 3
267	  if (len < 400) return 4
268	  return 5
269	}
270	
271	function isSimilar(a, b) {
272	  var ba = getBucket(a)
273	  var bb = getBucket(b)
274	  var diff = Math.abs(a - b)
275	  if (ba === bb) {
276	    if (a < 32 || b < 32) return diff <= 4
277	    return diff <= (Math.min(a, b) >> 3)
278	  }
279	  if (Math.abs(ba - bb) === 1) {
280	    return diff <= Math.floor(Math.min(a, b) * 20 / 100)
281	  }
282	  return false
283	}
284	
285	function structFilter(ps) {
286	  for (var i = 2; i < ps.length; i++) {
287	    if (isSimilar(ps[i].len, ps[i - 1].len) && isSimilar(ps[i].len, ps[i - 2].len)) {
288	      ps[i].isAd = true
289	      ps[i].adTTL = AD_TTL_INIT
290	    }
291	  }
292	}
293	
294	// ==================== Step 3: 基础评分（整数版） ====================
295	
296	function baseScore(p) {
297	  var s = 0
298	  var text = p.text
299	  var len = text.length
300	
301	  // 中文密度
302	  var han = 0
303	  for (var i = 0; i < len; i++) {
304	    var c = text.charCodeAt(i)
305	    if (c >= 0x4e00 && c <= 0x9fa5) han++
306	  }
307	  var ratio = (han * INT_SCALE) / (len + 1)
308	  if (ratio > 700) s += 300
309	  else s -= 100
310	
311	  // 末尾标点（取最后一个非空白字符）
312	  var lastChar = ""
313	  for (var j = len - 1; j >= 0; j--) {
314	    var ch = text.charAt(j)
315	    if (ch !== " " && ch !== "\n" && ch !== "\r" && ch !== "\t" && ch !== ">") {
316	      lastChar = ch
317	      break
318	    }
319	  }
320	  if (lastChar === "。" || lastChar === "！" || lastChar === "？") {
321	    s += 300
322	  } else {
323	    s -= 50
324	  }
325	
326	  // 副标题弱增强
327	  if (len < 18) s += 80
328	
329	  return s
330	}
331	
332	// ==================== Step 3.5: LQB（Low Quality Buffer） ====================
333	
334	function lqb(ps) {
335	  for (var i = 0; i < ps.length; i++) {
336	    if (i > 0) {
337	      ps[i].lowScoreStreak = (ps[i].score < LQB_LOW_THRESHOLD)
338	        ? ps[i - 1].lowScoreStreak + 1
339	        : 0
340	    } else {
341	      ps[i].lowScoreStreak = (ps[i].score < LQB_LOW_THRESHOLD) ? 1 : 0
342	    }
343	  }
344	}
345	
346	// ==================== Step 3.6: adTTL（广告衰减传播） ====================
347	
348	function adTTL(ps) {
349	  // adTTL 衰减传播
350	  for (var i = 1; i < ps.length; i++) {
351	    if (ps[i - 1].adTTL > 0) {
352	      ps[i].adTTL = Math.max(ps[i].adTTL, ps[i - 1].adTTL - AD_DECAY)
353	    }
354	  }
355	
356	  // 广告影响：adTTL > 0 的段落轻度压制
357	  for (var j = 0; j < ps.length; j++) {
358	    if (ps[j].adTTL > 0) {
359	      ps[j].score = Math.floor(ps[j].score * (1 - AD_BOOST_NEAR_AD))
360	    }
361	  }
362	}
363	
364	// ==================== Step 4: 单向邻域增强（i-1） ====================
365	
366	function smooth(ps) {
367	  var out = []
368	  for (var i = 0; i < ps.length; i++) {
369	    var s = ps[i].score
370	    if (i > 0 && !ps[i].isAd && !ps[i - 1].isAd) {
371	      s += Math.floor(ps[i - 1].score * 3 / 10)
372	    }
373	    out.push(s)
374	  }
375	  return out
376	}
377	
378	// ==================== Step 5: Kadane-lite 最大子段和 ====================
379	
380	function kadane(arr) {
381	  var max = -1000000000
382	  var sum = 0
383	  var start = 0
384	  var bestL = 0
385	  var bestR = 0
386	
387	  for (var i = 0; i < arr.length; i++) {
388	    if (sum <= 0) {
389	      sum = arr[i]
390	      start = i
391	    } else {
392	      sum += arr[i]
393	    }
394	    if (sum > max) {
395	      max = sum
396	      bestL = start
397	      bestR = i
398	    }
399	  }
400	  return { bestL: bestL, bestR: bestR }
401	}
402	
403	// ==================== 核心算法：Tecko-R ====================
404	
405	/**
406	 * Tecko-R 正文提取算法
407	 * @param {string} html - 原始 HTML
408	 * @returns {string} - 提取的正文 HTML（含原始标签）
409	 */
410	function teckoR(html) {
411	  if (!html || html.length < 50) return ""
412	
413	  var ps = extractP(html)
414	  if (ps.length === 0) return ""
415	
416	  structFilter(ps)
417	
418	  for (var i = 0; i < ps.length; i++) {
419	    ps[i].score = baseScore(ps[i])
420	    if (ps[i].isAd) ps[i].score = Math.min(ps[i].score, 10)
421	  }
422	
423	  // Step 3.5: LQB 连续低质量检测
424	  lqb(ps)
425	
426	  // Step 3.6: adTTL 广告衰减传播
427	  adTTL(ps)
428	
429	  // Ring Buffer: 超出 MAX_P 时淘汰低分段
430	  if (ps.length > MAX_P) {
431	    ps.sort(function (a, b) { return b.score - a.score })
432	    ps = ps.slice(0, MAX_P)
433	  }
434	
435	  var sm = smooth(ps)
436	  var region = kadane(sm)
437	
438	  var out = ""
439	  for (var j = region.bestL; j <= region.bestR; j++) {
440	    out += ps[j].text
441	  }
442	  return out
443	}
444	
445	// ==================== SPA 检测 ====================
446	
447	/**
448	 * 检测是否为 SPA 页面（特征 + DOM 特征 AND 运算）
449	 * @param {string} html
450	 * @returns {boolean}
451	 */
452	function isSPA(html) {
453	  var hasFramework = html.indexOf("__INITIAL_STATE__") !== -1 ||
454	                     html.indexOf("__DATA__") !== -1 ||
455	                     html.indexOf("window.__") !== -1
456	  var hasEmptyApp = (html.indexOf('id="app"') !== -1 || html.indexOf("id='app'") !== -1) &&
457	                    html.indexOf("<div") !== -1
458	  var hasLittleContent = html.length < 5000
459	  return hasFramework && hasEmptyApp && hasLittleContent
460	}
461	
462	// ==================== 重定向检测 ====================
463	
464	/**
465	 * 检测 HTML 中的重定向（meta refresh / JS 跳转）
466	 * @param {string} html
467	 * @param {string} currentUrl
468	 * @returns {string|null} - 重定向 URL 或 null
469	 */
470	function detectRedirect(html, currentUrl) {
471	  // meta refresh
472	  var metaRefresh = /<meta[^>]*http-equiv=["']?refresh["']?[^>]*content=["']?\d+\s*;\s*url=([^"'\s>]+)["']?/i.exec(html)
473	  if (metaRefresh && metaRefresh[1]) return resolveUrl(metaRefresh[1], currentUrl)
474	
475	  // JS 跳转
476	  var patterns = [
477	    /(?:window\.location\.href|location\.href)\s*=\s*["']([^"']+)["']/i,
478	    /(?:window\.location\.replace|location\.replace)\s*\(\s*["']([^"']+)["']\s*\)/i,
479	    /(?:window\.location|location)\s*=\s*["']([^"']+)["']/i,
480	    /window\.open\s*\(\s*["']([^"']+)["']\s*\)/i
481	  ]
482	  for (var i = 0; i < patterns.length; i++) {
483	    var match = patterns[i].exec(html)
484	    if (match && match[1] && match[1].length > 10 && match[1].indexOf("http") === 0 && match[1] !== currentUrl) {
485	      return match[1]
486	    }
487	  }
488	  return null
489	}
490	
491	/**
492	 * 相对路径转绝对路径
493	 */
494	function resolveUrl(relative, base) {
495	  if (relative.indexOf("http") === 0) return relative
496	  try {
497	    var baseObj = new URL(base)
498	    if (relative.indexOf("//") === 0) return baseObj.protocol + relative
499	    if (relative.indexOf("/") === 0) return baseObj.origin + relative
500	    var basePath = baseObj.pathname.substring(0, baseObj.pathname.lastIndexOf("/") + 1)
501	    return baseObj.origin + basePath + relative
502	  } catch (e) {
503	    return relative
504	  }
505	}
506	
507	// ==================== Script 数据提取（SPA fallback） ====================
508	
509	/**
510	 * 从 script 标签中提取嵌入的 JSON 数据
511	 */
512	function extractFromScripts(html) {
513	  var scriptRegex = /<script[^>]*>([\s\S]*?)<\/script>/gi
514	  var match
515	  while ((match = scriptRegex.exec(html)) !== null) {
516	    var scriptContent = match[1]
517	    if (!scriptContent || scriptContent.length < 100) continue
518	
519	    // window.__INITIAL_STATE__ = {...}
520	    var stateMatch = scriptContent.match(/window\.__\w+__\s*=\s*(\{[\s\S]+\})\s*;?\s*$/m)
521	    if (stateMatch) {
522	      try {
523	        var json = JSON.parse(stateMatch[1])
524	        var content = findContentInJson(json)
525	        if (content) return content
526	      } catch (e) {}
527	    }
528	
529	    // 直接 JSON
530	    if (scriptContent.trim().charAt(0) === "{") {
531	      try {
532	        var json2 = JSON.parse(scriptContent.trim())
533	        var content2 = findContentInJson(json2)
534	        if (content2) return content2
535	      } catch (e) {}
536	    }
537	
538	    // "content": "..."
539	    var contentMatch = scriptContent.match(/"content"\s*:\s*"([^"]{100,})"/)
540	    if (contentMatch) return decodeScriptContent(contentMatch[1])
541	
542	    var bodyMatch = scriptContent.match(/"body"\s*:\s*"([^"]{100,})"/)
543	    if (bodyMatch) return decodeScriptContent(bodyMatch[1])
544	
545	    var descMatch = scriptContent.match(/"description"\s*:\s*"([^"]{100,})"/)
546	    if (descMatch) return descMatch[1].replace(/\\n/g, "\n").replace(/\\"/g, '"')
547	  }
548	  return ""
549	}
550	
551	function decodeScriptContent(raw) {
552	  raw = raw.replace(/\\n/g, "\n").replace(/\\t/g, "\t").replace(/\\"/g, '"')
553	  raw = raw.replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"')
554	  raw = raw.replace(/<[^>]+>/g, "\n")
555	  raw = raw.split(/[\r\n]+/).map(function (l) { return l.trim() }).filter(function (l) { return l.length > 0 }).join("\n\n")
556	  return raw.length > 50 ? raw : ""
557	}
558	
559	function findContentInJson(obj) {
560	  if (!obj || typeof obj !== "object") return ""
561	  var keys = ["content", "body", "html", "articleContent", "articleBody", "detailContent"]
562	  for (var i = 0; i < keys.length; i++) {
563	    var val = obj[keys[i]]
564	    if (typeof val === "string" && val.length > 100) {
565	      var text = val.replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"')
566	      text = text.replace(/<[^>]+>/g, "\n")
567	      text = text.split(/[\r\n]+/).map(function (l) { return l.trim() }).filter(function (l) { return l.length > 0 }).join("\n\n")
568	      if (text.length > 50) return text
569	    }
570	  }
571	  var childKeys = Object.keys(obj)
572	  for (var j = 0; j < childKeys.length; j++) {
573	    var child = obj[childKeys[j]]
574	    if (typeof child === "object" && child !== null) {
575	      var result = findContentInJson(child)
576	      if (result) return result
577	    }
578	  }
579	  return ""
580	}
581	
582	// ==================== 后处理 ====================
583	
584	/**
585	 * 解码 HTML 实体 + 去标签，保留段落分隔
586	 * @param {string} html
587	 * @returns {string} - 纯文本，段落间用双换行分隔
588	 */
589	function decodeAndStrip(html) {
590	  if (!html) return ""
591	  var map = {
592	    "nbsp": " ", "ensp": " ", "emsp": " ", "thinsp": " ",
593	    "quot": "\"", "apos": "'", "lt": "<", "gt": ">",
594	    "amp": "&",
595	    "mdash": "—", "ndash": "–", "hellip": "…",
596	    "lsquo": "‘", "rsquo": "’",
597	    "ldquo": "“", "rdquo": "”",
598	    "copy": "©", "reg": "®", "trade": "™",
599	    "bull": "•", "middot": "·"
600	  }
601	  // 段落标签转双换行
602	  html = html.replace(/<\/p>\s*<p[^>]*>/gi, "\n\n")
603	  html = html.replace(/<p[^>]*>/gi, "")
604	  html = html.replace(/<\/p>/gi, "")
605	  // 去其他标签
606	  html = html.replace(/<[^>]+>/g, " ")
607	  // 解码命名实体
608	  html = html.replace(/&([a-zA-Z]+);?/g, function (m, name) {
609	    var val = map[name]
610	    return val !== undefined ? val : m
611	  })
612	  // 解码数字实体
613	  html = html.replace(/&#(\d+);?/g, function (m, code) {
614	    var n = parseInt(code, 10)
615	    return (n >= 32 && n <= 65535) ? String.fromCharCode(n) : m
616	  })
617	  // 解码十六进制实体
618	  html = html.replace(/&#x([0-9a-fA-F]+);?/g, function (m, hex) {
619	    var n = parseInt(hex, 16)
620	    return (n >= 32 && n <= 65535) ? String.fromCharCode(n) : m
621	  })
622	  // 合并连续空格（保留换行）
623	  html = html.replace(/[^\S\n]+/g, " ")
624	  // 合并连续空行为双换行
625	  html = html.replace(/\n{3,}/g, "\n\n")
626	  return html.trim()
627	}
628	
629	// ==================== CAPTCHA 检测 ====================
630	
631	function isCaptchaPage(html) {
632	  var lower = html.toLowerCase()
633	  return lower.indexOf("verify") !== -1 ||
634	         lower.indexOf("captcha") !== -1 ||
635	         lower.indexOf("人机验证") !== -1 ||
636	         lower.indexOf("滑动验证") !== -1 ||
637	         lower.indexOf("请完成安全验证") !== -1 ||
638	         lower.indexOf("access denied") !== -1 ||
639	         lower.indexOf("checking your browser") !== -1 ||
640	         lower.indexOf("just a moment") !== -1 ||
641	         lower.indexOf("ray id") !== -1
642	}
643	
644	// ==================== 主管线 ====================
645	
646	/**
647	 * 完整正文提取管线
648	 * @param {string} url - 新闻 URL
649	 * @param {object} fetchImpl - fetch 实现
650	 * @param {function} [onLog] - 日志回调（可选）
651	 * @returns {Promise<string>} - 提取的纯文本正文
652	 */
653	function extract(url, fetchImpl, onLog) {
654	  var log = onLog || function () {}
655	  return fetchWithRedirect(url, 0, fetchImpl, log)
656	}
657	
658	function fetchWithRedirect(url, depth, fetchImpl, log) {
659	  if (depth > MAX_REDIRECT) {
660	    log("重定向次数过多，停止")
661	    return Promise.resolve("")
662	  }
663	
664	  log("请求URL (depth=" + depth + "): " + url)
665	
666	  return fetchText(url, fetchImpl).then(function (data) {
667	    // HTTP 3xx 重定向
668	    if (data && typeof data === "object" && data.redirect) {
669	      log("HTTP重定向: " + url + " -> " + data.redirect)
670	      return fetchWithRedirect(data.redirect, depth + 1, fetchImpl, log)
671	    }
672	
673	    if (!data || data.length < 50) {
674	      log("响应内容过短或为空")
675	      return ""
676	    }
677	
678	    log("响应内容长度: " + data.length)
679	
680	    // CAPTCHA 检测
681	    if (isCaptchaPage(data)) {
682	      log("检测到人机验证页面，跳过")
683	      return ""
684	    }
685	
686	    // HTML 重定向检测
687	    var redirectUrl = detectRedirect(data, url)
688	    if (redirectUrl) {
689	      log("HTML重定向: " + url + " -> " + redirectUrl)
690	      return fetchWithRedirect(redirectUrl, depth + 1, fetchImpl, log)
691	    }
692	
693	    // SPA script 数据提取
694	    var scriptData = extractFromScripts(data)
695	    if (scriptData && scriptData.length > 50) {
696	      log("从script提取到内容，长度=" + scriptData.length)
697	      return scriptData
698	    }
699	
700	    // Tecko-R 正文提取
701	    log("Tecko-R 开始处理，HTML长度=" + data.length)
702	    var rawResult = teckoR(data)
703	    log("Tecko-R 原始结果长度=" + (rawResult ? rawResult.length : 0))
704	
705	    if (!rawResult || rawResult.length < 30) {
706	      log("Tecko-R 结果过短")
707	      return ""
708	    }
709	
710	    // 后处理
711	    var decoded = decodeAndStrip(rawResult)
712	    log("Tecko-R 后处理结果长度=" + decoded.length)
713	    return decoded
714	  }).catch(function (err) {
715	    log("请求失败: " + url + " - " + err.message)
716	    return ""
717	  })
718	}
719	
720	// ==================== 导出 ====================
721	
722	module.exports = {
723	  // 完整管线（推荐使用）
724	  extract: extract,
725	
726	  // 核心算法（可单独使用）
727	  teckoR: teckoR,
728	
729	  // 后处理
730	  decodeAndStrip: decodeAndStrip,
731	
732	  // 工具函数
733	  isSPA: isSPA,
734	  isCaptchaPage: isCaptchaPage,
735	  detectRedirect: detectRedirect,
736	  extractFromScripts: extractFromScripts,
737	
738	  // 配置常量
739	  MAX_P: MAX_P,
740	  INT_SCALE: INT_SCALE
741	}
