// ===== Step 4: Score 融合层（NewRepair2 统一层） =====
// effective_score[i] = raw_score[i] + α * raw_score[i-1] - 30 * traversability[i]
// α = 0.20, penalty_scale = 30

var SCORE_ALPHA = 20   // 0.20 * 100，整数运算
var PENALTY_SCALE = 30

function scoreFusion(ps) {
  for (var i = 0; i < ps.length; i++) {
    var bonus = (i > 0) ? Math.floor(ps[i - 1].score * SCORE_ALPHA / 100) : 0
    var penalty = Math.floor(PENALTY_SCALE * (ps[i].traversability || 0))
    ps[i].effectiveScore = ps[i].score + bonus - penalty
  }
}

// ===== Step 5: 单向邻域增强（i-1） =====

function smooth(ps) {
  var out = []
  for (var i = 0; i < ps.length; i++) {
    var s = ps[i].effectiveScore !== undefined ? ps[i].effectiveScore : ps[i].score
    if (i > 0) {
      var prevScore = ps[i - 1].effectiveScore !== undefined ? ps[i - 1].effectiveScore : ps[i - 1].score
      s += Math.floor(prevScore * 3 / 10)
    }
    out.push(s)
  }
  return out
}

