var KADANE_BASE_T = -120

function kadane(arr) {
  var max = -1000000000
  var sum = 0
  var start = 0
  var bestL = 0
  var bestR = 0

  for (var i = 0; i < arr.length; i++) {
    if (sum < KADANE_BASE_T) {
      sum = arr[i]
      start = i
    } else {
      sum += arr[i]
    }
    if (sum > max) {
      max = sum
      bestL = start
      bestR = i
    }
  }

  return { bestL: bestL, bestR: bestR }
}

