// ===== Step 3.25: BOVL（Boundary-Oriented Validation Layer v2） =====
// 从 gate model → recovery model：输出连续分 bovl_score ∈ [-0.3, +0.3]
// 组合评分：sim信号 + role匹配 + 结构提示

// 字符 bigram 相似度（无 embedding，JerryScript 可用）
function sim(a, b) {
  a = a.replace(/[^一-龥a-zA-Z0-9]/g, "")
  b = b.replace(/[^一-龥a-zA-Z0-9]/g, "")
  var map = {}
  var inter = 0
  for (var i = 0; i < a.length - 1; i++) {
    map[a[i] + a[i + 1]] = 1
  }
  for (var j = 0; j < b.length - 1; j++) {
    if (map[b[j] + b[j + 1]]) inter++
  }
  return inter / (a.length + b.length + 1)
}

// 结构角色识别（扩展版：6 种角色）
function segRole(seg, idx, total) {
  var tag = seg.tag || "p"
  var text = seg.text || ""
  var cleanText = text.replace(/<[^>]+>/g, "").trim()

  if (tag === "blockquote") return "QUOTE"
  if (tag === "cite") return "SOURCE"
  if (idx === 0 || /^新华社|记者|报道|中新网|本报|编辑/.test(cleanText)) return "LEAD"
  if (/评论|认为|分析|指出|表示|认为/.test(cleanText) && cleanText.length < 100) return "COMMENT"
  if (/^(?:但是|然而|此外|同时|另外|不过|与此同时|据了解)/.test(cleanText)) return "TRANSITION"
  return "BODY"
}

// BOVL 组合评分：返回 [-0.3, +0.3]
function bovlScore(seg, prev, next, idx, total) {
  var cleanText = seg.text.replace(/<[^>]+>/g, "").trim()
  var prevText = prev ? prev.text.replace(/<[^>]+>/g, "").trim() : ""
  var nextText = next ? next.text.replace(/<[^>]+>/g, "").trim() : ""

  var simPrev = prevText ? sim(cleanText, prevText) : 0
  var simNext = nextText ? sim(cleanText, nextText) : 0
  var simMax = simPrev > simNext ? simPrev : simNext

  var r = segRole(seg, idx, total)

  // 组合评分
  var score = 0

  // 1. sim 信号（权重 0.5）：与上下文有连续性
  score += 0.5 * (simMax > 0.15 ? 1 : 0)

  // 2. role 匹配（权重 0.3）：结构性段落不应被误杀
  var roleMatch = (r === "QUOTE" || r === "SOURCE" || r === "LEAD" || r === "COMMENT") ? 1 : 0
  score += 0.3 * roleMatch

  // 3. 结构提示（权重 0.2）：基于标签和文本特征
  var tag = seg.tag || "p"
  var hint = (tag !== "p" || r === "TRANSITION") ? 1 : 0
  score += 0.2 * hint

  // 归一化到 [-0.3, +0.3]
  return (score - 0.5) * 0.6
}

// 对所有段落执行 BOVL 修正
function bovlPass(ps) {
  for (var i = 0; i < ps.length; i++) {
    var bs = bovlScore(ps[i], ps[i - 1], ps[i + 1], i, ps.length)
    ps[i].bovlScore = bs

    // 正分段：BOVL 加成；负分段：BOVL 修复
    var adjustment = Math.floor(bs * 100)
    if (adjustment !== 0) {
      ps[i].originalScore = ps[i].score
      ps[i].score = ps[i].score + adjustment
      ps[i].bovlAdjusted = true
      console.log("BOVL: [" + i + "] " + segRole(ps[i], i, ps.length) + " bs=" + bs.toFixed(2) + " score " + ps[i].originalScore + " → " + ps[i].score)
    }
  }
}

