/**
 * Tecko-R v1.4: 单遍流式 DOM 语义过滤 + 门控融合 + Kadane 正文区间检测
 * 适配 QuickApp (JerryScript) 环境：无 DOM API，纯字符串扫描
 *
 * Pipeline: extractP → structFilter → baseScore → LQB → adTTL → scoreFusion → smooth → Kadane
 * NR4 最终版：trav 为门控变量（1=放行, 0=阻断），Kadane 经典版
 */

var MAX_P = 64
var INT_SCALE = 1000

// 语义容器特征词
var SEMANTIC_WORDS = ["content", "article", "detail", "main", "body", "text"]

// 排除标签
var EXCLUDED_TAGS = ["nav", "footer", "aside", "header"]

// LQB 参数
var LQB_LOW_THRESHOLD = 120
var LQB_WINDOW_LIMIT = 3

// adTTL 参数
var AD_TTL_INIT = 3
var AD_DECAY = 1
var AD_BOOST_NEAR_AD = 0.15

// ===== Step 1: 段落提取（字符串状态机 + 有界子树传播） =====

function extractP(html) {
  var res = []
  var lower = html.toLowerCase()
  var len = html.length
  var pos = 0
  var inExcluded = 0
  var inSemantic = 0
  var inPlain = 0

  while (pos < len) {
    var ltPos = lower.indexOf("<", pos)
    if (ltPos === -1) break

    // 检测排除标签
    var skipEx = false
    for (var ei = 0; ei < EXCLUDED_TAGS.length; ei++) {
      var exTag = EXCLUDED_TAGS[ei]
      var exOpen = "<" + exTag
      if (lower.indexOf(exOpen, ltPos) === ltPos &&
          (ltPos + exOpen.length >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + exOpen.length)) !== -1)) {
        var exClose = lower.indexOf("</" + exTag + ">", ltPos + exOpen.length)
        if (exClose === -1) { pos = len; skipEx = true; break }
        pos = exClose + exTag.length + 3
        skipEx = true
        break
      }
      var exCloseTag = "</" + exTag + ">"
      if (lower.indexOf(exCloseTag, ltPos) === ltPos) {
        if (inExcluded > 0) inExcluded--
        pos = ltPos + exCloseTag.length
        skipEx = true
        break
      }
    }
    if (skipEx) continue
    if (pos > ltPos) continue

    // 检测语义容器开标签
    if (inExcluded === 0) {
      var containerTags = ["article", "section"]
      var foundContainer = false
      for (var ci = 0; ci < containerTags.length; ci++) {
        var cTag = containerTags[ci]
        var cOpen = "<" + cTag
        if (lower.indexOf(cOpen, ltPos) === ltPos &&
            (ltPos + cOpen.length >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + cOpen.length)) !== -1)) {
          inSemantic++
          pos = ltPos + cOpen.length
          foundContainer = true
          break
        }
      }
      if (foundContainer) continue

      // 语义 div 检测
      if (lower.indexOf("<div", ltPos) === ltPos &&
          (ltPos + 4 >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + 4)) !== -1)) {
        var divEnd = lower.indexOf(">", ltPos)
        if (divEnd === -1) break
        var divAttrs = lower.substring(ltPos, divEnd + 1)
        var isSemantic = false
        for (var si = 0; si < SEMANTIC_WORDS.length; si++) {
          if (divAttrs.indexOf(SEMANTIC_WORDS[si]) !== -1) {
            isSemantic = true
            break
          }
        }
        if (isSemantic) { inSemantic++ } else { inPlain++ }
        pos = divEnd + 1
        continue
      }
    }

    // 检测容器闭标签
    if (lower.indexOf("</article>", ltPos) === ltPos) {
      if (inSemantic > 0) inSemantic--
      pos = ltPos + 10; continue
    }
    if (lower.indexOf("</section>", ltPos) === ltPos) {
      if (inSemantic > 0) inSemantic--
      pos = ltPos + 10; continue
    }
    if (lower.indexOf("</div>", ltPos) === ltPos) {
      if (inSemantic > 0) inSemantic--
      else if (inPlain > 0) inPlain--
      pos = ltPos + 6; continue
    }

    // P 标签提取（仅在语义容器内）
    if (inExcluded === 0 && inSemantic > 0 && inPlain === 0) {
      if (lower.indexOf("<p", ltPos) === ltPos &&
          (ltPos + 2 >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + 2)) !== -1)) {
        var pClose = lower.indexOf("</p>", ltPos + 2)
        if (pClose === -1) break
        var text = html.substring(ltPos, pClose + 4)
        if (text.length > 10) {
          res.push({
            text: text,
            len: text.length,
            score: 0,
            isAd: false,
            lowScoreStreak: 0,
            traversability: 0,
            adTTL: 0,
            adFlag: 0
          })
          if (res.length >= MAX_P) break
        }
        pos = pClose + 4
        continue
      }
    }

    // 跳过 script/style 标签
    if (lower.indexOf("<script", ltPos) === ltPos &&
        (ltPos + 7 >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + 7)) !== -1)) {
      var sEnd = lower.indexOf("</script>", ltPos + 7)
      pos = sEnd === -1 ? len : sEnd + 9; continue
    }
    if (lower.indexOf("<style", ltPos) === ltPos &&
        (ltPos + 6 >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + 6)) !== -1)) {
      var stEnd = lower.indexOf("</style>", ltPos + 6)
      pos = stEnd === -1 ? len : stEnd + 8; continue
    }

    pos = ltPos + 1
  }

  // Fallback：无语义容器时，提取排除区外的 P 标签
  if (res.length === 0) {
    pos = 0
    while (pos < len) {
      var lt2 = lower.indexOf("<", pos)
      if (lt2 === -1) break

      var skip = false
      for (var fi = 0; fi < EXCLUDED_TAGS.length; fi++) {
        var fTag = EXCLUDED_TAGS[fi]
        if (lower.indexOf("<" + fTag, lt2) === lt2 &&
            (lt2 + fTag.length + 1 >= len || " >/\n\r\t".indexOf(lower.charAt(lt2 + fTag.length + 1)) !== -1)) {
          var fClose = lower.indexOf("</" + fTag + ">", lt2 + fTag.length + 1)
          pos = fClose === -1 ? len : fClose + fTag.length + 3
          skip = true; break
        }
      }
      if (skip) continue

      if (lower.indexOf("<p", lt2) === lt2 &&
          (lt2 + 2 >= len || " >/\n\r\t".indexOf(lower.charAt(lt2 + 2)) !== -1)) {
        var pEnd = lower.indexOf("</p>", lt2 + 2)
        if (pEnd === -1) break
        var t = html.substring(lt2, pEnd + 4)
        if (t.length > 10) {
          res.push({
            text: t,
            len: t.length,
            score: 0,
            isAd: false,
            lowScoreStreak: 0,
            traversability: 0,
            adTTL: 0,
            adFlag: 0
          })
          if (res.length >= MAX_P) break
        }
        pos = pEnd + 4; continue
      }

      if (lower.indexOf("<script", lt2) === lt2 &&
          (lt2 + 7 >= len || " >/\n\r\t".indexOf(lower.charAt(lt2 + 7)) !== -1)) {
        var scrEnd = lower.indexOf("</script>", lt2 + 7)
        pos = scrEnd === -1 ? len : scrEnd + 9; continue
      }
      if (lower.indexOf("<style", lt2) === lt2 &&
          (lt2 + 6 >= len || " >/\n\r\t".indexOf(lower.charAt(lt2 + 6)) !== -1)) {
        var styEnd = lower.indexOf("</style>", lt2 + 6)
        pos = styEnd === -1 ? len : styEnd + 8; continue
      }

      pos = lt2 + 1
    }
  }

  return res
}

// ===== Step 2: 结构过滤（长度桶 + 区间相似性） =====

function getBucket(len) {
  if (len < 20) return 0
  if (len < 50) return 1
  if (len < 100) return 2
  if (len < 200) return 3
  if (len < 400) return 4
  return 5
}

function isSimilar(a, b) {
  var ba = getBucket(a)
  var bb = getBucket(b)
  var diff = Math.abs(a - b)
  if (ba === bb) {
    if (a < 32 || b < 32) return diff <= 4
    return diff <= (Math.min(a, b) >> 3)
  }
  if (Math.abs(ba - bb) === 1) {
    return diff <= Math.floor(Math.min(a, b) * 20 / 100)
  }
  return false
}

function structFilter(ps) {
  for (var i = 2; i < ps.length; i++) {
    if (isSimilar(ps[i].len, ps[i - 1].len) && isSimilar(ps[i].len, ps[i - 2].len)) {
      ps[i].isAd = true
      ps[i].adTTL = AD_TTL_INIT
    }
  }
}

// ===== Step 3: 基础评分（整数版） =====

function baseScore(p) {
  var s = 0
  var text = p.text
  var len = text.length

  // 中文密度
  var han = 0
  for (var i = 0; i < len; i++) {
    var c = text.charCodeAt(i)
    if (c >= 0x4e00 && c <= 0x9fa5) han++
  }
  var ratio = (han * INT_SCALE) / (len + 1)
  if (ratio > 700) s += 300
  else s -= 100

  // 末尾标点（取 HTML 内最后一个非空白字符）
  var lastChar = ""
  for (var j = len - 1; j >= 0; j--) {
    var ch = text.charAt(j)
    if (ch !== " " && ch !== "\n" && ch !== "\r" && ch !== "\t" && ch !== ">") {
      lastChar = ch
      break
    }
  }
  if (lastChar === "。" || lastChar === "！" || lastChar === "？") {
    s += 300
  } else {
    s -= 50
  }

  // 副标题弱增强
  if (len < 18) s += 80

  return s
}

// ===== Step 3.5: LQB（Low Quality Buffer） =====
// 输出 traversability ∈ [0,1]
// trav = 1 → 放行，trav = 0 → 阻断
// streak 高（连续低质量）→ trav 低（不可穿越）

function lqb(ps) {
  for (var i = 0; i < ps.length; i++) {
    if (i > 0) {
      ps[i].lowScoreStreak = (ps[i].score < LQB_LOW_THRESHOLD)
        ? ps[i - 1].lowScoreStreak + 1
        : 0
    } else {
      ps[i].lowScoreStreak = (ps[i].score < LQB_LOW_THRESHOLD) ? 1 : 0
    }
    ps[i].traversability = 1 - Math.min(ps[i].lowScoreStreak / LQB_WINDOW_LIMIT, 1)
  }
}

// ===== Step 3.6: adTTL（广告衰减传播） =====

function adTTL(ps) {
  // adTTL 衰减传播
  for (var i = 1; i < ps.length; i++) {
    if (ps[i - 1].adTTL > 0) {
      ps[i].adTTL = Math.max(ps[i].adTTL, ps[i - 1].adTTL - AD_DECAY)
    }
  }

  // 广告影响：adTTL > 0 的段落轻度压制
  for (var j = 0; j < ps.length; j++) {
    if (ps[j].adTTL > 0) {
      ps[j].score = Math.floor(ps[j].score * (1 - AD_BOOST_NEAR_AD))
    }
  }
}

// ===== Step 4: Score 融合层（门控模型） =====
// eff = score * (0.85 + 0.15 * trav)
// trav=1 → eff = score（完全保留）
// trav=0 → eff = score * 0.85（轻度衰减）

function scoreFusion(ps) {
  for (var i = 0; i < ps.length; i++) {
    var trav = ps[i].traversability || 0
    ps[i].effectiveScore = Math.floor(ps[i].score * (85 + Math.floor(15 * trav)) / 100)
  }
}

// ===== Step 5: 单向邻域增强（i-1） =====

function smooth(ps) {
  var out = []
  for (var i = 0; i < ps.length; i++) {
    var s = ps[i].effectiveScore !== undefined ? ps[i].effectiveScore : ps[i].score
    if (i > 0) {
      var prevScore = ps[i - 1].effectiveScore !== undefined ? ps[i - 1].effectiveScore : ps[i - 1].score
      s += Math.floor(prevScore * 3 / 10)
    }
    out.push(s)
  }
  return out
}

// ===== Step 6: Kadane-lite 最大子段和（经典版，纯函数） =====

function kadane(arr) {
  var max = -1000000000
  var sum = 0
  var start = 0
  var bestL = 0
  var bestR = 0

  for (var i = 0; i < arr.length; i++) {
    if (sum <= 0) {
      sum = arr[i]
      start = i
    } else {
      sum += arr[i]
    }
    if (sum > max) {
      max = sum
      bestL = start
      bestR = i
    }
  }

  return { bestL: bestL, bestR: bestR }
}

// ===== SPA 检测 =====

function isSPA(html) {
  var hasFramework = html.indexOf("__INITIAL_STATE__") !== -1 ||
                     html.indexOf("__DATA__") !== -1 ||
                     html.indexOf("window.__") !== -1
  var hasEmptyApp = (html.indexOf('id="app"') !== -1 || html.indexOf("id='app'") !== -1) &&
                    html.indexOf("<div") !== -1
  var hasLittleContent = html.length < 5000
  return hasFramework && hasEmptyApp && hasLittleContent
}

// ===== 主函数 =====

function teckoR(html) {
  if (!html || html.length < 50) return ""

  // Step 1: 提取段落
  var ps = extractP(html)
  if (ps.length === 0) return ""

  console.log("=== Tecko-R 评分表 ===")
  console.log("提取段落数: " + ps.length)

  // Step 2: 结构过滤（标记 isAd + 初始化 adTTL）
  structFilter(ps)

  // Step 3: 基础评分
  for (var i = 0; i < ps.length; i++) {
    ps[i].score = baseScore(ps[i])
    if (ps[i].isAd) {
      ps[i].score = Math.min(ps[i].score, 10)
    }
  }

  // Step 3.5: LQB 连续低质量检测
  lqb(ps)

  // Step 3.6: adTTL 广告衰减传播
  adTTL(ps)

  // Step 4: Score 融合层（门控模型）
  scoreFusion(ps)

  // 打印评分表
  console.log("┌────┬───────┬─────┬─────┬───────┬───────┬──────────────────────────────┐")
  console.log("│ #  │ score │ Ad  │ LQB │ trav  │ eff   │ text                         │")
  console.log("├────┼───────┼─────┼─────┼───────┼───────┼──────────────────────────────┤")
  for (var p = 0; p < ps.length; p++) {
    var item = ps[p]
    var textPreview = item.text.replace(/<[^>]+>/g, "").substring(0, 28)
    textPreview = textPreview.replace(/\n/g, " ").replace(/\r/g, "")
    console.log("│ " + pad(p, 2) + " │ " + pad(item.score, 5) + " │ " + pad(item.isAd ? "Y" : "N", 3) + " │ " + pad(item.lowScoreStreak, 3) + " │ " + pad(item.traversability.toFixed(1), 5) + " │ " + pad(item.effectiveScore, 5) + " │ " + padRight(textPreview, 28) + " │")
  }
  console.log("└────┴───────┴─────┴─────┴───────┴───────┴──────────────────────────────┘")

  // Ring Buffer: 超出 MAX_P 时淘汰低分段
  if (ps.length > MAX_P) {
    console.log("RingBuffer: 淘汰 " + (ps.length - MAX_P) + " 个低分段")
    ps.sort(function (a, b) { return b.score - a.score })
    ps = ps.slice(0, MAX_P)
  }

  // Step 5: 单向邻域增强
  var sm = smooth(ps)

  // Step 6: Kadane-lite（经典版，纯函数）
  var region = kadane(sm)

  console.log("Kadane 选择区间: [" + region.bestL + ", " + region.bestR + "]")

  // 打印 Kadane 选择的段落
  console.log("选中段落:")
  for (var j = region.bestL; j <= region.bestR; j++) {
    var selText = ps[j].text.replace(/<[^>]+>/g, "").substring(0, 50)
    console.log("  [" + j + "] score=" + sm[j] + " text=" + selText)
  }

  // 拼接输出
  var out = ""
  for (var k = region.bestL; k <= region.bestR; k++) {
    out += ps[k].text
  }

  return out
}

function pad(n, width) {
  var s = String(n)
  while (s.length < width) s = " " + s
  return s
}

function padRight(s, width) {
  if (s.length >= width) return s.substring(0, width)
  while (s.length < width) s = s + " "
  return s
}

module.exports = teckoR

/**
 * Tecko-R v1.7: 结构感知提取 + BOVL 误伤修复/噪声压制 + 门控融合 + Kadane 正文区间检测
 * 适配 QuickApp (JerryScript) 环境：无 DOM API，纯字符串扫描
 *
 * Pipeline: extractP(structural) → structFilter → baseScore → BOVL → LQB → adTTL → scoreFusion → smooth → Kadane
 * BOVL: 仅作用于 BSC<0 段，拆分为 RECOVER（回正）和 SUPPRESS（压制）
 */

var MAX_P = 64
var INT_SCALE = 1000

// 语义容器特征词
var SEMANTIC_WORDS = ["content", "article", "detail", "main", "body", "text"]

// 排除标签
var EXCLUDED_TAGS = ["nav", "footer", "aside", "header"]

// LQB 参数
var LQB_LOW_THRESHOLD = 120
var LQB_WINDOW_LIMIT = 3

// adTTL 参数
var AD_TTL_INIT = 3
var AD_DECAY = 1
var AD_BOOST_NEAR_AD = 0.15

// ===== Step 1: 段落提取（字符串状态机 + 有界子树传播 + 结构元数据） =====

// 内容标签：需要提取的正文相关标签
var CONTENT_TAGS = ["p", "blockquote", "cite"]

// 从开标签字符串中提取 tag / class / id
function parseTagAttrs(tagHtml) {
  var m = tagHtml.match(/^<(\w+)/)
  var tag = m ? m[1].toLowerCase() : "p"
  var cm = tagHtml.match(/class=["']([^"']+)["']/i)
  var im = tagHtml.match(/id=["']([^"']+)["']/i)
  return { tag: tag, className: cm ? cm[1] : "", id: im ? im[1] : "" }
}

// 创建段落对象
function makeSeg(text, attrs) {
  return {
    text: text,
    len: text.length,
    tag: attrs ? attrs.tag : "p",
    className: attrs ? attrs.className : "",
    id: attrs ? attrs.id : "",
    score: 0,
    bovlScore: 0,
    isAd: false,
    lowScoreStreak: 0,
    traversability: 0,
    adTTL: 0,
    adFlag: 0
  }
}

// 检测是否匹配指定标签开标签，返回标签名或 false
function matchOpenTag(lower, pos, len) {
  for (var i = 0; i < CONTENT_TAGS.length; i++) {
    var t = CONTENT_TAGS[i]
    var open = "<" + t
    if (lower.indexOf(open, pos) === pos &&
        (pos + open.length >= len || " >/\n\r\t".indexOf(lower.charAt(pos + open.length)) !== -1)) {
      return t
    }
  }
  return false
}

function extractP(html) {
  var res = []
  var lower = html.toLowerCase()
  var len = html.length
  var pos = 0
  var inExcluded = 0
  var inSemantic = 0
  var inPlain = 0

  while (pos < len) {
    var ltPos = lower.indexOf("<", pos)
    if (ltPos === -1) break

    // 检测排除标签
    var skipEx = false
    for (var ei = 0; ei < EXCLUDED_TAGS.length; ei++) {
      var exTag = EXCLUDED_TAGS[ei]
      var exOpen = "<" + exTag
      if (lower.indexOf(exOpen, ltPos) === ltPos &&
          (ltPos + exOpen.length >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + exOpen.length)) !== -1)) {
        var exClose = lower.indexOf("</" + exTag + ">", ltPos + exOpen.length)
        if (exClose === -1) { pos = len; skipEx = true; break }
        pos = exClose + exTag.length + 3
        skipEx = true
        break
      }
      var exCloseTag = "</" + exTag + ">"
      if (lower.indexOf(exCloseTag, ltPos) === ltPos) {
        if (inExcluded > 0) inExcluded--
        pos = ltPos + exCloseTag.length
        skipEx = true
        break
      }
    }
    if (skipEx) continue
    if (pos > ltPos) continue

    // 检测语义容器开标签
    if (inExcluded === 0) {
      var containerTags = ["article", "section"]
      var foundContainer = false
      for (var ci = 0; ci < containerTags.length; ci++) {
        var cTag = containerTags[ci]
        var cOpen = "<" + cTag
        if (lower.indexOf(cOpen, ltPos) === ltPos &&
            (ltPos + cOpen.length >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + cOpen.length)) !== -1)) {
          inSemantic++
          pos = ltPos + cOpen.length
          foundContainer = true
          break
        }
      }
      if (foundContainer) continue

      // 语义 div 检测
      if (lower.indexOf("<div", ltPos) === ltPos &&
          (ltPos + 4 >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + 4)) !== -1)) {
        var divEnd = lower.indexOf(">", ltPos)
        if (divEnd === -1) break
        var divAttrs = lower.substring(ltPos, divEnd + 1)
        var isSemantic = false
        for (var si = 0; si < SEMANTIC_WORDS.length; si++) {
          if (divAttrs.indexOf(SEMANTIC_WORDS[si]) !== -1) {
            isSemantic = true
            break
          }
        }
        if (isSemantic) { inSemantic++ } else { inPlain++ }
        pos = divEnd + 1
        continue
      }
    }

    // 检测容器闭标签
    if (lower.indexOf("</article>", ltPos) === ltPos) {
      if (inSemantic > 0) inSemantic--
      pos = ltPos + 10; continue
    }
    if (lower.indexOf("</section>", ltPos) === ltPos) {
      if (inSemantic > 0) inSemantic--
      pos = ltPos + 10; continue
    }
    if (lower.indexOf("</div>", ltPos) === ltPos) {
      if (inSemantic > 0) inSemantic--
      else if (inPlain > 0) inPlain--
      pos = ltPos + 6; continue
    }

    // 内容标签提取（p / blockquote / cite，仅在语义容器内）
    if (inExcluded === 0 && inSemantic > 0 && inPlain === 0) {
      var openTag = matchOpenTag(lower, ltPos, len)
      if (openTag) {
        var tagEnd = lower.indexOf(">", ltPos)
        if (tagEnd === -1) break
        var openHtml = html.substring(ltPos, tagEnd + 1)
        var closeTag = "</" + openTag + ">"
        var closePos = lower.indexOf(closeTag, tagEnd + 1)
        if (closePos === -1) break
        var text = html.substring(ltPos, closePos + closeTag.length)
        if (text.length > 10) {
          res.push(makeSeg(text, parseTagAttrs(openHtml)))
          if (res.length >= MAX_P) break
        }
        pos = closePos + closeTag.length
        continue
      }
    }

    // 跳过 script/style 标签
    if (lower.indexOf("<script", ltPos) === ltPos &&
        (ltPos + 7 >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + 7)) !== -1)) {
      var sEnd = lower.indexOf("</script>", ltPos + 7)
      pos = sEnd === -1 ? len : sEnd + 9; continue
    }
    if (lower.indexOf("<style", ltPos) === ltPos &&
        (ltPos + 6 >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + 6)) !== -1)) {
      var stEnd = lower.indexOf("</style>", ltPos + 6)
      pos = stEnd === -1 ? len : stEnd + 8; continue
    }

    pos = ltPos + 1
  }

  // Fallback：无语义容器时，提取排除区外的内容标签
  if (res.length === 0) {
    pos = 0
    while (pos < len) {
      var lt2 = lower.indexOf("<", pos)
      if (lt2 === -1) break

      var skip = false
      for (var fi = 0; fi < EXCLUDED_TAGS.length; fi++) {
        var fTag = EXCLUDED_TAGS[fi]
        if (lower.indexOf("<" + fTag, lt2) === lt2 &&
            (lt2 + fTag.length + 1 >= len || " >/\n\r\t".indexOf(lower.charAt(lt2 + fTag.length + 1)) !== -1)) {
          var fClose = lower.indexOf("</" + fTag + ">", lt2 + fTag.length + 1)
          pos = fClose === -1 ? len : fClose + fTag.length + 3
          skip = true; break
        }
      }
      if (skip) continue

      var fbTag = matchOpenTag(lower, lt2, len)
      if (fbTag) {
        var fbTagEnd = lower.indexOf(">", lt2)
        if (fbTagEnd === -1) break
        var fbOpenHtml = html.substring(lt2, fbTagEnd + 1)
        var fbClose = "</" + fbTag + ">"
        var fbClosePos = lower.indexOf(fbClose, fbTagEnd + 1)
        if (fbClosePos === -1) break
        var fbText = html.substring(lt2, fbClosePos + fbClose.length)
        if (fbText.length > 10) {
          res.push(makeSeg(fbText, parseTagAttrs(fbOpenHtml)))
          if (res.length >= MAX_P) break
        }
        pos = fbClosePos + fbClose.length; continue
      }

      if (lower.indexOf("<script", lt2) === lt2 &&
          (lt2 + 7 >= len || " >/\n\r\t".indexOf(lower.charAt(lt2 + 7)) !== -1)) {
        var scrEnd = lower.indexOf("</script>", lt2 + 7)
        pos = scrEnd === -1 ? len : scrEnd + 9; continue
      }
      if (lower.indexOf("<style", lt2) === lt2 &&
          (lt2 + 6 >= len || " >/\n\r\t".indexOf(lower.charAt(lt2 + 6)) !== -1)) {
        var styEnd = lower.indexOf("</style>", lt2 + 6)
        pos = styEnd === -1 ? len : styEnd + 8; continue
      }

      pos = lt2 + 1
    }
  }

  return res
}

// ===== Step 2: 结构过滤（长度桶 + 区间相似性） =====

function getBucket(len) {
  if (len < 20) return 0
  if (len < 50) return 1
  if (len < 100) return 2
  if (len < 200) return 3
  if (len < 400) return 4
  return 5
}

function isSimilar(a, b) {
  var ba = getBucket(a)
  var bb = getBucket(b)
  var diff = Math.abs(a - b)
  if (ba === bb) {
    if (a < 32 || b < 32) return diff <= 4
    return diff <= (Math.min(a, b) >> 3)
  }
  if (Math.abs(ba - bb) === 1) {
    return diff <= Math.floor(Math.min(a, b) * 20 / 100)
  }
  return false
}

function structFilter(ps) {
  for (var i = 2; i < ps.length; i++) {
    if (isSimilar(ps[i].len, ps[i - 1].len) && isSimilar(ps[i].len, ps[i - 2].len)) {
      ps[i].isAd = true
      ps[i].adTTL = AD_TTL_INIT
    }
  }
}

// ===== Step 3: 基础评分（整数版） =====

function baseScore(p) {
  var s = 0
  var text = p.text
  var len = text.length

  // 中文密度
  var han = 0
  for (var i = 0; i < len; i++) {
    var c = text.charCodeAt(i)
    if (c >= 0x4e00 && c <= 0x9fa5) han++
  }
  var ratio = (han * INT_SCALE) / (len + 1)
  if (ratio > 700) s += 300
  else s -= 100

  // 末尾标点（取 HTML 内最后一个非空白字符）
  var lastChar = ""
  for (var j = len - 1; j >= 0; j--) {
    var ch = text.charAt(j)
    if (ch !== " " && ch !== "\n" && ch !== "\r" && ch !== "\t" && ch !== ">") {
      lastChar = ch
      break
    }
  }
  if (lastChar === "。" || lastChar === "！" || lastChar === "？") {
    s += 300
  } else {
    s -= 50
  }

  // 副标题弱增强
  if (len < 18) s += 80

  return s
}

// ===== Step 3.25: BOVL（Boundary-Oriented Validation Layer v2） =====
// 仅作用于 BSC<0 段，拆分为可恢复正文与噪声
// 组合评分：sim信号 + role匹配 + 结构提示

// 字符 bigram 相似度
function sim(a, b) {
  a = a.replace(/[^一-龥a-zA-Z0-9]/g, "")
  b = b.replace(/[^一-龥a-zA-Z0-9]/g, "")
  var map = {}
  var inter = 0
  for (var i = 0; i < a.length - 1; i++) {
    map[a[i] + a[i + 1]] = 1
  }
  for (var j = 0; j < b.length - 1; j++) {
    if (map[b[j] + b[j + 1]]) inter++
  }
  return inter / (a.length + b.length + 1)
}

// 结构角色识别（6 种角色）
function segRole(seg, idx) {
  var tag = seg.tag || "p"
  var text = seg.text || ""
  var cleanText = text.replace(/<[^>]+>/g, "").trim()

  if (tag === "blockquote") return "QUOTE"
  if (tag === "cite") return "SOURCE"
  if (idx === 0 || /^新华社|记者|报道|中新网|本报|编辑/.test(cleanText)) return "LEAD"
  if (/评论|认为|分析|指出|表示/.test(cleanText) && cleanText.length < 100) return "COMMENT"
  if (/^(?:但是|然而|此外|同时|另外|不过|与此同时|据了解)/.test(cleanText)) return "TRANSITION"
  return "BODY"
}

// BOVL 组合评分：返回 [-0.3, +0.3]
function bovlScore(seg, prev, next, idx, total) {
  var cleanText = seg.text.replace(/<[^>]+>/g, "").trim()
  var prevText = prev ? prev.text.replace(/<[^>]+>/g, "").trim() : ""
  var nextText = next ? next.text.replace(/<[^>]+>/g, "").trim() : ""

  var simPrev = prevText ? sim(cleanText, prevText) : 0
  var simNext = nextText ? sim(cleanText, nextText) : 0
  var simMax = simPrev > simNext ? simPrev : simNext

  var r = segRole(seg, idx)

  var score = 0
  score += 0.5 * (simMax > 0.15 ? 1 : 0)
  var roleMatch = (r === "QUOTE" || r === "SOURCE" || r === "LEAD" || r === "COMMENT") ? 1 : 0
  score += 0.3 * roleMatch
  var tag = seg.tag || "p"
  var hint = (tag !== "p" || r === "TRANSITION") ? 1 : 0
  score += 0.2 * hint

  return (score - 0.5) * 0.6
}

// BOVL：仅作用于 BSC < 0 段
function bovlPass(ps) {
  for (var i = 0; i < ps.length; i++) {
    var bs = bovlScore(ps[i], ps[i - 1], ps[i + 1], i, ps.length)
    ps[i].bovlScore = bs

    if (ps[i].score >= 0) continue

    if (bs > 0) {
      var repair = Math.floor(bs * 100)
      ps[i].originalScore = ps[i].score
      ps[i].score = ps[i].score + repair
      ps[i].bovlAdjusted = true
      ps[i].bovlAction = "RECOVER"
      console.log("BOVL RECOVER: [" + i + "] " + segRole(ps[i], i) + " bs=" + bs.toFixed(2) + " " + ps[i].originalScore + " → " + ps[i].score)
    } else {
      var suppress = Math.floor(Math.abs(bs) * 60)
      ps[i].originalScore = ps[i].score
      ps[i].score = ps[i].score - suppress
      ps[i].bovlAdjusted = true
      ps[i].bovlAction = "SUPPRESS"
      console.log("BOVL SUPPRESS: [" + i + "] " + segRole(ps[i], i) + " bs=" + bs.toFixed(2) + " " + ps[i].originalScore + " → " + ps[i].score)
    }
  }
}

// ===== Step 3.5: LQB（Low Quality Buffer） =====

function lqb(ps) {
  for (var i = 0; i < ps.length; i++) {
    if (i > 0) {
      ps[i].lowScoreStreak = (ps[i].score < LQB_LOW_THRESHOLD)
        ? ps[i - 1].lowScoreStreak + 1
        : 0
    } else {
      ps[i].lowScoreStreak = (ps[i].score < LQB_LOW_THRESHOLD) ? 1 : 0
    }
    ps[i].traversability = 1 - Math.min(ps[i].lowScoreStreak / LQB_WINDOW_LIMIT, 1)
  }
}

// ===== Step 3.6: adTTL（广告衰减传播） =====

function adTTL(ps) {
  for (var i = 1; i < ps.length; i++) {
    if (ps[i - 1].adTTL > 0) {
      ps[i].adTTL = Math.max(ps[i].adTTL, ps[i - 1].adTTL - AD_DECAY)
    }
  }
  for (var j = 0; j < ps.length; j++) {
    if (ps[j].adTTL > 0) {
      ps[j].score = Math.floor(ps[j].score * (1 - AD_BOOST_NEAR_AD))
    }
  }
}

// ===== Step 4: Score 融合层（门控模型） =====
// trav < 0.5 → 噪声门关闭（score×0.4），trav >= 0.5 → 放行

function scoreFusion(ps) {
  for (var i = 0; i < ps.length; i++) {
    var trav = ps[i].traversability || 0
    if (trav < 0.5) {
      ps[i].effectiveScore = Math.floor(ps[i].score * 40 / 100)
      ps[i].isNoise = true
    } else {
      ps[i].effectiveScore = ps[i].score
      ps[i].isNoise = false
    }
  }
}

// ===== Step 5: 单向邻域增强（i-1） =====

function smooth(ps) {
  var out = []
  for (var i = 0; i < ps.length; i++) {
    var s = ps[i].effectiveScore !== undefined ? ps[i].effectiveScore : ps[i].score
    if (i > 0) {
      var prevScore = ps[i - 1].effectiveScore !== undefined ? ps[i - 1].effectiveScore : ps[i - 1].score
      s += Math.floor(prevScore * 3 / 10)
    }
    out.push(s)
  }
  return out
}

// ===== Step 6: Kadane-lite 最大子段和（经典版，纯函数） =====

function kadane(arr) {
  var max = -1000000000
  var sum = 0
  var start = 0
  var bestL = 0
  var bestR = 0

  for (var i = 0; i < arr.length; i++) {
    if (sum <= 0) {
      sum = arr[i]
      start = i
    } else {
      sum += arr[i]
    }
    if (sum > max) {
      max = sum
      bestL = start
      bestR = i
    }
  }

  return { bestL: bestL, bestR: bestR }
}

// ===== SPA 检测 =====

function isSPA(html) {
  var hasFramework = html.indexOf("__INITIAL_STATE__") !== -1 ||
                     html.indexOf("__DATA__") !== -1 ||
                     html.indexOf("window.__") !== -1
  var hasEmptyApp = (html.indexOf('id="app"') !== -1 || html.indexOf("id='app'") !== -1) &&
                    html.indexOf("<div") !== -1
  var hasLittleContent = html.length < 5000
  return hasFramework && hasEmptyApp && hasLittleContent
}

// ===== 主函数 =====

function teckoR(html) {
  if (!html || html.length < 50) return ""

  var ps = extractP(html)
  if (ps.length === 0) return ""

  console.log("=== Tecko-R 评分表 ===")
  console.log("提取段落数: " + ps.length)

  structFilter(ps)

  for (var i = 0; i < ps.length; i++) {
    ps[i].score = baseScore(ps[i])
    if (ps[i].isAd) {
      ps[i].score = Math.min(ps[i].score, 10)
    }
  }

  // Step 3.25: BOVL 重审核（仅 BSC<0 段）
  bovlPass(ps)

  // Step 3.5: LQB
  lqb(ps)

  // Step 3.6: adTTL
  adTTL(ps)

  // Step 4: Score 融合层
  scoreFusion(ps)

  // 打印评分表
  console.log("┌────┬───────┬─────┬───────┬──────┬─────┬───────┬───────┬─────┬──────────────────────┐")
  console.log("│ #  │ score │ Ad  │ BOV_s │ BOVL │ LQB │ trav  │ eff   │ N   │ text                 │")
  console.log("├────┼───────┼─────┼───────┼──────┼─────┼───────┼───────┼─────┼──────────────────────┤")
  for (var p = 0; p < ps.length; p++) {
    var item = ps[p]
    var textPreview = item.text.replace(/<[^>]+>/g, "").substring(0, 20)
    textPreview = textPreview.replace(/\n/g, " ").replace(/\r/g, "")
    var bovScoreLabel = (item.bovlScore !== undefined) ? item.bovlScore.toFixed(2) : "0.00"
    var bovActionLabel = item.bovlAction || "---"
    console.log("│ " + pad(p, 2) + " │ " + pad(item.score, 5) + " │ " + pad(item.isAd ? "Y" : "N", 3) + " │ " + pad(bovScoreLabel, 5) + " │ " + padRight(bovActionLabel, 4) + " │ " + pad(item.lowScoreStreak, 3) + " │ " + pad(item.traversability.toFixed(1), 5) + " │ " + pad(item.effectiveScore, 5) + " │ " + pad(item.isNoise ? "Y" : "N", 3) + " │ " + padRight(textPreview, 20) + " │")
  }
  console.log("└────┴───────┴─────┴───────┴──────┴─────┴───────┴───────┴─────┴──────────────────────┘")

  if (ps.length > MAX_P) {
    console.log("RingBuffer: 淘汰 " + (ps.length - MAX_P) + " 个低分段")
    ps.sort(function (a, b) { return b.score - a.score })
    ps = ps.slice(0, MAX_P)
  }

  var sm = smooth(ps)
  var region = kadane(sm)

  console.log("Kadane 选择区间: [" + region.bestL + ", " + region.bestR + "]")
  console.log("选中段落:")
  for (var j = region.bestL; j <= region.bestR; j++) {
    var selText = ps[j].text.replace(/<[^>]+>/g, "").substring(0, 50)
    console.log("  [" + j + "] score=" + sm[j] + " text=" + selText)
  }

  var out = ""
  for (var k = region.bestL; k <= region.bestR; k++) {
    out += ps[k].text
  }

  return out
}

function pad(n, width) {
  var s = String(n)
  while (s.length < width) s = " " + s
  return s
}

function padRight(s, width) {
  if (s.length >= width) return s.substring(0, width)
  while (s.length < width) s = s + " "
  return s
}

module.exports = teckoR

/**
 * Tecko-R v2.0: 单源评分 + 标签过滤 + Kadane 纯执行
 * 适配 QuickApp (JerryScript) 环境：无 DOM API，纯字符串扫描
 *
 * Pipeline: extractP → structFilter → baseScore → label(BOVL+SUPP) → Kadane前过滤 → Kadane
 * 核心原则：BSC 是唯一分数源，BOVL/SUPP 只打标签不改分，Kadane 在干净势能序列上执行
 */

var MAX_P = 64
var INT_SCALE = 1000

// 语义容器特征词
var SEMANTIC_WORDS = ["content", "article", "detail", "main", "body", "text"]

// 排除标签
var EXCLUDED_TAGS = ["nav", "footer", "aside", "header"]

// LQB 参数
var LQB_LOW_THRESHOLD = 120
var LQB_WINDOW_LIMIT = 3

// adTTL 参数
var AD_TTL_INIT = 3
var AD_DECAY = 1
var AD_BOOST_NEAR_AD = 0.15

// ===== Step 1: 段落提取（字符串状态机 + 有界子树传播 + 结构元数据） =====

var CONTENT_TAGS = ["p", "blockquote", "cite"]

function parseTagAttrs(tagHtml) {
  var m = tagHtml.match(/^<(\w+)/)
  var tag = m ? m[1].toLowerCase() : "p"
  var cm = tagHtml.match(/class=["']([^"']+)["']/i)
  var im = tagHtml.match(/id=["']([^"']+)["']/i)
  return { tag: tag, className: cm ? cm[1] : "", id: im ? im[1] : "" }
}

function makeSeg(text, attrs) {
  return {
    text: text,
    len: text.length,
    tag: attrs ? attrs.tag : "p",
    className: attrs ? attrs.className : "",
    id: attrs ? attrs.id : "",
    score: 0,
    label: "NORMAL",
    isAd: false,
    lowScoreStreak: 0,
    traversability: 0,
    adTTL: 0,
    adFlag: 0
  }
}

function matchOpenTag(lower, pos, len) {
  for (var i = 0; i < CONTENT_TAGS.length; i++) {
    var t = CONTENT_TAGS[i]
    var open = "<" + t
    if (lower.indexOf(open, pos) === pos &&
        (pos + open.length >= len || " >/\n\r\t".indexOf(lower.charAt(pos + open.length)) !== -1)) {
      return t
    }
  }
  return false
}

function extractP(html) {
  var res = []
  var lower = html.toLowerCase()
  var len = html.length
  var pos = 0
  var inExcluded = 0
  var inSemantic = 0
  var inPlain = 0

  while (pos < len) {
    var ltPos = lower.indexOf("<", pos)
    if (ltPos === -1) break

    var skipEx = false
    for (var ei = 0; ei < EXCLUDED_TAGS.length; ei++) {
      var exTag = EXCLUDED_TAGS[ei]
      var exOpen = "<" + exTag
      if (lower.indexOf(exOpen, ltPos) === ltPos &&
          (ltPos + exOpen.length >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + exOpen.length)) !== -1)) {
        var exClose = lower.indexOf("</" + exTag + ">", ltPos + exOpen.length)
        if (exClose === -1) { pos = len; skipEx = true; break }
        pos = exClose + exTag.length + 3
        skipEx = true
        break
      }
      var exCloseTag = "</" + exTag + ">"
      if (lower.indexOf(exCloseTag, ltPos) === ltPos) {
        if (inExcluded > 0) inExcluded--
        pos = ltPos + exCloseTag.length
        skipEx = true
        break
      }
    }
    if (skipEx) continue
    if (pos > ltPos) continue

    if (inExcluded === 0) {
      var containerTags = ["article", "section"]
      var foundContainer = false
      for (var ci = 0; ci < containerTags.length; ci++) {
        var cTag = containerTags[ci]
        var cOpen = "<" + cTag
        if (lower.indexOf(cOpen, ltPos) === ltPos &&
            (ltPos + cOpen.length >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + cOpen.length)) !== -1)) {
          inSemantic++
          pos = ltPos + cOpen.length
          foundContainer = true
          break
        }
      }
      if (foundContainer) continue

      if (lower.indexOf("<div", ltPos) === ltPos &&
          (ltPos + 4 >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + 4)) !== -1)) {
        var divEnd = lower.indexOf(">", ltPos)
        if (divEnd === -1) break
        var divAttrs = lower.substring(ltPos, divEnd + 1)
        var isSemantic = false
        for (var si = 0; si < SEMANTIC_WORDS.length; si++) {
          if (divAttrs.indexOf(SEMANTIC_WORDS[si]) !== -1) {
            isSemantic = true
            break
          }
        }
        if (isSemantic) { inSemantic++ } else { inPlain++ }
        pos = divEnd + 1
        continue
      }
    }

    if (lower.indexOf("</article>", ltPos) === ltPos) {
      if (inSemantic > 0) inSemantic--
      pos = ltPos + 10; continue
    }
    if (lower.indexOf("</section>", ltPos) === ltPos) {
      if (inSemantic > 0) inSemantic--
      pos = ltPos + 10; continue
    }
    if (lower.indexOf("</div>", ltPos) === ltPos) {
      if (inSemantic > 0) inSemantic--
      else if (inPlain > 0) inPlain--
      pos = ltPos + 6; continue
    }

    if (inExcluded === 0 && inSemantic > 0 && inPlain === 0) {
      var openTag = matchOpenTag(lower, ltPos, len)
      if (openTag) {
        var tagEnd = lower.indexOf(">", ltPos)
        if (tagEnd === -1) break
        var openHtml = html.substring(ltPos, tagEnd + 1)
        var closeTag = "</" + openTag + ">"
        var closePos = lower.indexOf(closeTag, tagEnd + 1)
        if (closePos === -1) break
        var text = html.substring(ltPos, closePos + closeTag.length)
        if (text.length > 10) {
          res.push(makeSeg(text, parseTagAttrs(openHtml)))
          if (res.length >= MAX_P) break
        }
        pos = closePos + closeTag.length
        continue
      }
    }

    if (lower.indexOf("<script", ltPos) === ltPos &&
        (ltPos + 7 >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + 7)) !== -1)) {
      var sEnd = lower.indexOf("</script>", ltPos + 7)
      pos = sEnd === -1 ? len : sEnd + 9; continue
    }
    if (lower.indexOf("<style", ltPos) === ltPos &&
        (ltPos + 6 >= len || " >/\n\r\t".indexOf(lower.charAt(ltPos + 6)) !== -1)) {
      var stEnd = lower.indexOf("</style>", ltPos + 6)
      pos = stEnd === -1 ? len : stEnd + 8; continue
    }

    pos = ltPos + 1
  }

  if (res.length === 0) {
    pos = 0
    while (pos < len) {
      var lt2 = lower.indexOf("<", pos)
      if (lt2 === -1) break

      var skip = false
      for (var fi = 0; fi < EXCLUDED_TAGS.length; fi++) {
        var fTag = EXCLUDED_TAGS[fi]
        if (lower.indexOf("<" + fTag, lt2) === lt2 &&
            (lt2 + fTag.length + 1 >= len || " >/\n\r\t".indexOf(lower.charAt(lt2 + fTag.length + 1)) !== -1)) {
          var fClose = lower.indexOf("</" + fTag + ">", lt2 + fTag.length + 1)
          pos = fClose === -1 ? len : fClose + fTag.length + 3
          skip = true; break
        }
      }
      if (skip) continue

      var fbTag = matchOpenTag(lower, lt2, len)
      if (fbTag) {
        var fbTagEnd = lower.indexOf(">", lt2)
        if (fbTagEnd === -1) break
        var fbOpenHtml = html.substring(lt2, fbTagEnd + 1)
        var fbClose = "</" + fbTag + ">"
        var fbClosePos = lower.indexOf(fbClose, fbTagEnd + 1)
        if (fbClosePos === -1) break
        var fbText = html.substring(lt2, fbClosePos + fbClose.length)
        if (fbText.length > 10) {
          res.push(makeSeg(fbText, parseTagAttrs(fbOpenHtml)))
          if (res.length >= MAX_P) break
        }
        pos = fbClosePos + fbClose.length; continue
      }

      if (lower.indexOf("<script", lt2) === lt2 &&
          (lt2 + 7 >= len || " >/\n\r\t".indexOf(lower.charAt(lt2 + 7)) !== -1)) {
        var scrEnd = lower.indexOf("</script>", lt2 + 7)
        pos = scrEnd === -1 ? len : scrEnd + 9; continue
      }
      if (lower.indexOf("<style", lt2) === lt2 &&
          (lt2 + 6 >= len || " >/\n\r\t".indexOf(lower.charAt(lt2 + 6)) !== -1)) {
        var styEnd = lower.indexOf("</style>", lt2 + 6)
        pos = styEnd === -1 ? len : styEnd + 8; continue
      }

      pos = lt2 + 1
    }
  }

  return res
}

// ===== Step 2: 结构过滤（长度桶 + 区间相似性） =====

function getBucket(len) {
  if (len < 20) return 0
  if (len < 50) return 1
  if (len < 100) return 2
  if (len < 200) return 3
  if (len < 400) return 4
  return 5
}

function isSimilar(a, b) {
  var ba = getBucket(a)
  var bb = getBucket(b)
  var diff = Math.abs(a - b)
  if (ba === bb) {
    if (a < 32 || b < 32) return diff <= 4
    return diff <= (Math.min(a, b) >> 3)
  }
  if (Math.abs(ba - bb) === 1) {
    return diff <= Math.floor(Math.min(a, b) * 20 / 100)
  }
  return false
}

function structFilter(ps) {
  for (var i = 2; i < ps.length; i++) {
    if (isSimilar(ps[i].len, ps[i - 1].len) && isSimilar(ps[i].len, ps[i - 2].len)) {
      ps[i].isAd = true
      ps[i].adTTL = AD_TTL_INIT
    }
  }
}

// ===== Step 3: BSC 基础评分（唯一分数源，冻结） =====

function baseScore(p) {
  var s = 0
  var text = p.text
  var len = text.length

  var han = 0
  for (var i = 0; i < len; i++) {
    var c = text.charCodeAt(i)
    if (c >= 0x4e00 && c <= 0x9fa5) han++
  }
  var ratio = (han * INT_SCALE) / (len + 1)
  if (ratio > 700) s += 300
  else s -= 100

  var lastChar = ""
  for (var j = len - 1; j >= 0; j--) {
    var ch = text.charAt(j)
    if (ch !== " " && ch !== "\n" && ch !== "\r" && ch !== "\t" && ch !== ">") {
      lastChar = ch
      break
    }
  }
  if (lastChar === "。" || lastChar === "！" || lastChar === "？") {
    s += 300
  } else {
    s -= 50
  }

  if (len < 18) s += 80

  return s
}

// ===== Step 3.5: 标签系统（只打标签，不改分数） =====

// 字符 bigram 相似度
function sim(a, b) {
  a = a.replace(/[^一-龥a-zA-Z0-9]/g, "")
  b = b.replace(/[^一-龥a-zA-Z0-9]/g, "")
  var map = {}
  var inter = 0
  for (var i = 0; i < a.length - 1; i++) {
    map[a[i] + a[i + 1]] = 1
  }
  for (var j = 0; j < b.length - 1; j++) {
    if (map[b[j] + b[j + 1]]) inter++
  }
  return inter / (a.length + b.length + 1)
}

// 结构角色识别
function segRole(seg, idx) {
  var tag = seg.tag || "p"
  var text = seg.text || ""
  var cleanText = text.replace(/<[^>]+>/g, "").trim()

  if (tag === "blockquote") return "QUOTE"
  if (tag === "cite") return "SOURCE"
  if (idx === 0 || /^新华社|记者|报道|中新网|本报|编辑/.test(cleanText)) return "LEAD"
  if (/评论|认为|分析|指出|表示/.test(cleanText) && cleanText.length < 100) return "COMMENT"
  if (/^(?:但是|然而|此外|同时|另外|不过|与此同时|据了解)/.test(cleanText)) return "TRANSITION"
  return "BODY"
}

// BOVL 标签：RECOVERABLE（疑似正文误伤）或 NORMAL
function bovlLabel(seg, prev, next, idx) {
  if (seg.score >= 0) return "NORMAL"

  var cleanText = seg.text.replace(/<[^>]+>/g, "").trim()
  var prevText = prev ? prev.text.replace(/<[^>]+>/g, "").trim() : ""
  var nextText = next ? next.text.replace(/<[^>]+>/g, "").trim() : ""

  var simPrev = prevText ? sim(cleanText, prevText) : 0
  var simNext = nextText ? sim(cleanText, nextText) : 0
  var simMax = simPrev > simNext ? simPrev : simNext

  var r = segRole(seg, idx)

  // 结构性段落：引用/来源/导语/评论 → 可恢复
  if (r === "QUOTE" || r === "SOURCE" || r === "LEAD" || r === "COMMENT") return "RECOVERABLE"

  // 与上下文连续 → 可恢复
  if (simMax > 0.15) return "RECOVERABLE"

  return "NORMAL"
}

// SUPP 标签：SUPPRESSIBLE（垃圾/广告）或 NOISE
function suppLabel(seg) {
  // 广告标记 → 可压制
  if (seg.isAd) return "SUPPRESSIBLE"

  // 极低分 + 极短 → 可压制
  if (seg.score < -200 && seg.len < 30) return "SUPPRESSIBLE"

  return "NOISE"
}

// 对所有段落打标签（不改分数）
function labelPass(ps) {
  for (var i = 0; i < ps.length; i++) {
    ps[i].bovlTag = bovlLabel(ps[i], ps[i - 1], ps[i + 1], i)
    ps[i].suppTag = suppLabel(ps[i])
  }
}

// ===== Step 4: Kadane 前过滤（单次，基于标签） =====

function kadanePrefilter(ps) {
  for (var i = 0; i < ps.length; i++) {
    if (ps[i].suppTag === "SUPPRESSIBLE") {
      ps[i].kadaneInput = -1000000000
    } else if (ps[i].bovlTag === "RECOVERABLE") {
      ps[i].kadaneInput = Math.max(ps[i].score, 0)
    } else {
      ps[i].kadaneInput = ps[i].score
    }
  }
}

// ===== Step 5: Kadane-lite（纯执行层） =====

function kadane(arr) {
  var max = -1000000000
  var sum = 0
  var start = 0
  var bestL = 0
  var bestR = 0

  for (var i = 0; i < arr.length; i++) {
    if (sum <= 0) {
      sum = arr[i]
      start = i
    } else {
      sum += arr[i]
    }
    if (sum > max) {
      max = sum
      bestL = start
      bestR = i
    }
  }

  return { bestL: bestL, bestR: bestR }
}

// ===== 主函数 =====

function teckoR(html) {
  if (!html || html.length < 50) return ""

  var ps = extractP(html)
  if (ps.length === 0) return ""

  console.log("=== Tecko-R v2.0 ===")
  console.log("提取段落数: " + ps.length)

  structFilter(ps)

  // BSC：唯一分数源
  for (var i = 0; i < ps.length; i++) {
    ps[i].score = baseScore(ps[i])
    if (ps[i].isAd) {
      ps[i].score = Math.min(ps[i].score, 10)
    }
  }

  // 标签系统：只打标签，不改分数
  labelPass(ps)

  // Kadane 前过滤：基于标签做单次决策
  kadanePrefilter(ps)

  // 打印评分表
  console.log("┌────┬───────┬─────┬─────┬────────────┬────────────┬──────────┬────────────────────┐")
  console.log("│ #  │ score │ Ad  │ tag │ BOVL       │ SUPP       │ kadaneIn │ text               │")
  console.log("├────┼───────┼─────┼─────┼────────────┼────────────┼──────────┼────────────────────┤")
  for (var p = 0; p < ps.length; p++) {
    var item = ps[p]
    var textPreview = item.text.replace(/<[^>]+>/g, "").substring(0, 18)
    textPreview = textPreview.replace(/\n/g, " ").replace(/\r/g, "")
    var kadIn = item.kadaneInput === -1000000000 ? "-∞" : String(item.kadaneInput)
    console.log("│ " + pad(p, 2) + " │ " + pad(item.score, 5) + " │ " + pad(item.isAd ? "Y" : "N", 3) + " │ " + padRight(item.tag || "p", 3) + " │ " + padRight(item.bovlTag, 10) + " │ " + padRight(item.suppTag, 10) + " │ " + padRight(kadIn, 8) + " │ " + padRight(textPreview, 18) + " │")
  }
  console.log("└────┴───────┴─────┴─────┴────────────┴────────────┴──────────┴────────────────────┘")

  // Ring Buffer
  if (ps.length > MAX_P) {
    console.log("RingBuffer: 淘汰 " + (ps.length - MAX_P) + " 个低分段")
    ps.sort(function (a, b) { return b.score - a.score })
    ps = ps.slice(0, MAX_P)
  }

  // Kadane：在 kadaneInput 序列上执行
  var kadaneArr = []
  for (var ki = 0; ki < ps.length; ki++) {
    kadaneArr.push(ps[ki].kadaneInput)
  }
  var region = kadane(kadaneArr)

  console.log("Kadane 选择区间: [" + region.bestL + ", " + region.bestR + "]")
  console.log("选中段落:")
  for (var j = region.bestL; j <= region.bestR; j++) {
    var selText = ps[j].text.replace(/<[^>]+>/g, "").substring(0, 50)
    console.log("  [" + j + "] score=" + ps[j].score + " kadaneIn=" + ps[j].kadaneInput + " text=" + selText)
  }

  var out = ""
  for (var k = region.bestL; k <= region.bestR; k++) {
    out += ps[k].text
  }

  return out
}

function pad(n, width) {
  var s = String(n)
  while (s.length < width) s = " " + s
  return s
}

function padRight(s, width) {
  if (s.length >= width) return s.substring(0, width)
  while (s.length < width) s = s + " "
  return s
}

module.exports = teckoR

