  var cleanText = text.replace(/<[^>]+>/g, "").trim()

  if (tag === "blockquote") return "QUOTE"
  if (tag === "cite") return "SOURCE"
  if (idx === 0 || /^新华社|记者|报道|中新网|本报|编辑/.test(cleanText)) return "LEAD"
  if (/评论|认为|分析|指出|表示/.test(cleanText) && cleanText.length < 100) return "COMMENT"
  if (/^(?:但是|然而|此外|同时|另外|不过|与此同时|据了解)/.test(cleanText)) return "TRANSITION"
  return "BODY"
}

// BOVL 标签：RECOVERABLE（疑似正文误伤）或 NORMAL
function bovlLabel(seg, prev, next, idx) {
  if (seg.score >= 0) return "NORMAL"

  var cleanText = seg.text.replace(/<[^>]+>/g, "").trim()
  var prevText = prev ? prev.text.replace(/<[^>]+>/g, "").trim() : ""
  var nextText = next ? next.text.replace(/<[^>]+>/g, "").trim() : ""

  var simPrev = prevText ? sim(cleanText, prevText) : 0
  var simNext = nextText ? sim(cleanText, nextText) : 0
  var simMax = simPrev > simNext ? simPrev : simNext

  var r = segRole(seg, idx)

  // 结构性段落：引用/来源/导语/评论 → 可恢复
  if (r === "QUOTE" || r === "SOURCE" || r === "LEAD" || r === "COMMENT") return "RECOVERABLE"

  // 与上下文连续 → 可恢复
  if (simMax > 0.15) return "RECOVERABLE"

  return "NORMAL"
}

// SUPP 标签：SUPPRESSIBLE（垃圾/广告）或 NORMAL
function suppLabel(seg) {
  if (seg.isAd) return "SUPPRESSIBLE"
  if (seg.score < -200 && seg.len < 30) return "SUPPRESSIBLE"
  return "NORMAL"
}

// 对所有段落打标签（不改分数）
function labelPass(ps) {
  for (var i = 0; i < ps.length; i++) {
    ps[i].bovlTag = bovlLabel(ps[i], ps[i - 1], ps[i + 1], i)
    ps[i].suppTag = suppLabel(ps[i])
  }
}

// ===== Step 4: Energy Builder（唯一允许改数值的地方） =====

function buildEnergy(seg) {
  if (seg.suppTag === "SUPPRESSIBLE") return -Infinity
  if (seg.bovlTag === "RECOVERABLE") return Math.max(seg.score, 0)
  return seg.score
}

function energyPass(ps) {
  for (var i = 0; i < ps.length; i++) {
    ps[i].energy = buildEnergy(ps[i])
  }
}

